/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

/** gradients.sh "limb" palette; the deep stop takes the accent. */
const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

interface VennMergeProps {
  sets?: string[];
  center?: string;
  caption?: string;
  accent?: string;
  /** Frames the circles take to slide together. */
  slide?: number;
  /** Stroke width of the circles, in px at 720p. */
  ringWidth?: number;
  /** Replaces the remocn logo shown when `center` is "remocn". */
  logo?: React.ReactNode;
  /** Color of the set labels; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the set labels. Load it yourself; Instrument Serif by default. */
  fontFamily?: string;
  /** Size of the diagram and caption, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    ring: "rgba(243,242,239,0.62)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    ring: "rgba(18,18,20,0.6)",
    grain: 0.045,
  },
} as const;

const DRAW = [0, 24];
const SLIDE = [26, 66];
const FILL = [62, 84];
const BRAND = 74;
const CAPTION = 96;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function VennMergeBase({
  sets = ["Design", "Code"],
  center = "remocn",
  caption = "Motion design, written as code.",
  accent = "#3B5BFD",
  slide: slideDur = SLIDE[1] - SLIDE[0],
  ringWidth = 2,
  logo,
  ink,
  background,
  fontFamily = serif,
  scale = 1,
  delay = 0,
  grain = true,
  theme = "dark",
  speed = 1,
}: VennMergeProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height } = useSceneConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const bg =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const list = (sets.length ? sets : ["Design", "Code"]).slice(0, 3);
  const n = list.length;
  const three = n === 3;

  const R = height * (three ? 0.25 : 0.34);
  const cx = width / 2;
  const cy =
    height * (caption ? 0.45 : 0.5) +
    (three ? (R * 0.92) / Math.sqrt(3) / 4 : 0);
  const ring = Math.max(1.5, ringWidth * u);

  const slide = interpolate(t, [SLIDE[0], SLIDE[0] + slideDur], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const draw = interpolate(t, [DRAW[0], DRAW[1]], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const fill = interpolate(t, [FILL[0], FILL[1]], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const brand = interpolate(t, [BRAND, BRAND + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const capIn = interpolate(t, [CAPTION, CAPTION + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const push = interpolate(t, [0, CAPTION + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const pushScale = 0.965 + 0.035 * push;

  const finalSep = three ? R * 0.92 : R * 0.52;
  const startSep = three ? R * 1.15 : R * 2.24;
  const sepAt = (k: number) => startSep + (finalSep - startSep) * k;

  const dirs = three
    ? [
        { x: -Math.sqrt(3) / 2, y: 0.5 },
        { x: Math.sqrt(3) / 2, y: 0.5 },
        { x: 0, y: -1 },
      ]
    : [
        { x: -1, y: 0 },
        { x: 1, y: 0 },
      ];
  const reachAt = (k: number) =>
    three ? sepAt(k) / Math.sqrt(3) : sepAt(k) / 2;
  const reach = reachAt(slide);
  const centers = dirs.map((d) => ({
    x: cx + d.x * reach,
    y: cy + d.y * reach,
  }));

  const labelSize = (three ? 36 : 42) * u;
  const labelAt = (d: { x: number; y: number }, k: number) => {
    const off = three ? R * 0.42 * k : R - Math.min(2 * R, sepAt(k)) / 2;
    const r = reachAt(k) + off;
    return { x: cx + d.x * r, y: cy + d.y * r };
  };
  const labels = list.map((name, i) => {
    const d = dirs[i];
    // Layout rounds a baseline to whole pixels, so a label carried by
    // `left`/`top` steps as the circles slide. It is laid out where it
    // settles and the slide is a transform, exactly 0 once settled.
    const rest = labelAt(d, 1);
    const now = labelAt(d, slide);
    return {
      name,
      x: rest.x,
      y: rest.y,
      dx: now.x - rest.x,
      dy: now.y - rest.y,
      a: interpolate(t, [DRAW[0] + 4 + i * 3, DRAW[0] + 20 + i * 3], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      }),
    };
  });

  const regionW = three
    ? 2 * (R - finalSep / Math.sqrt(3)) * 0.95
    : (2 * R - finalSep) * 0.86;
  const isLogo = center.trim().toLowerCase() === "remocn";
  const brandSize = Math.min(
    84 * u,
    (regionW * 0.8) / (isLogo ? 3.75 : Math.max(center.length, 3) * 0.56),
  );
  const glowX =
    R * interpolate(t, [FILL[0], CAPTION + 60], [-0.12, 0.12], CLAMP);
  const brandY = cy;

  const circ = 2 * Math.PI * R;

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            // The push carries every label, so its tilt covers them all.
            transform: `scale(${pushScale})${glide(t > 0 && t < CAPTION + 40)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <defs>
              {centers.map((c, i) => (
                <clipPath id={`${uid}c${i}`} key={list[i]}>
                  <circle cx={c.x} cy={c.y} r={R} />
                </clipPath>
              ))}
              <radialGradient
                id={`${uid}g`}
                gradientUnits="userSpaceOnUse"
                cx={cx + glowX}
                cy={cy + R * 0.95}
                r={R * 1.75}
              >
                <stop offset={0} stopColor={LIMB[0]} />
                <stop offset={0.2} stopColor={LIMB[1]} />
                <stop offset={0.5} stopColor={accent} />
                <stop offset={0.74} stopColor={LIMB[2]} />
                <stop offset={1} stopColor={LIMB[3]} />
              </radialGradient>
              <radialGradient
                id={`${uid}h`}
                gradientUnits="userSpaceOnUse"
                cx={cx - glowX * 1.4}
                cy={cy - R * 0.55}
                r={R * 0.75}
              >
                <stop offset={0} stopColor={LIMB[1]} stopOpacity={0.55} />
                <stop offset={1} stopColor={LIMB[1]} stopOpacity={0} />
              </radialGradient>
            </defs>
            {centers.map((c, i) => (
              <circle
                key={list[i]}
                cx={c.x}
                cy={c.y}
                r={R}
                fill="none"
                stroke={p.ring}
                strokeWidth={ring}
                strokeDasharray={`${circ * draw} ${circ}`}
                transform={`rotate(${i === 0 ? 180 : three && i === 2 ? -90 : 0} ${c.x} ${c.y})`}
              />
            ))}
            {fill > 0 ? (
              <g clipPath={`url(#${uid}c0)`}>
                <g clipPath={`url(#${uid}c1)`}>
                  <g clipPath={three ? `url(#${uid}c2)` : undefined}>
                    <rect
                      x={cx - R * 2}
                      y={cy + R - 2 * R * fill}
                      width={R * 4}
                      height={2 * R * fill}
                      fill={`url(#${uid}g)`}
                    />
                    <rect
                      x={cx - R * 2}
                      y={cy + R - 2 * R * fill}
                      width={R * 4}
                      height={2 * R * fill}
                      fill={`url(#${uid}h)`}
                    />
                  </g>
                </g>
              </g>
            ) : null}
          </svg>

          {labels.map((l) => (
            <div
              key={l.name}
              style={{
                position: "absolute",
                left: l.x,
                top: l.y,
                transform: `translate(-50%, -50%) translate(${l.dx}px, ${l.dy + (1 - l.a) * 8 * u}px)`,
                fontFamily,
                fontWeight: 400,
                fontSize: labelSize,
                letterSpacing: "-0.01em",
                lineHeight: 1,
                color: fg,
                opacity: l.a,
                whiteSpace: "nowrap",
              }}
            >
              {l.name}
            </div>
          ))}

          <div
            style={{
              position: "absolute",
              left: cx,
              top: brandY,
              transform: `translate(-50%, -50%) translateY(${(1 - brand) * 18 * u}px) scale(${1.06 - 0.06 * brand})`,
              whiteSpace: "nowrap",
              opacity: brand,
              filter:
                brand < 0.99 ? `blur(${(1 - brand) * 8 * u}px)` : undefined,
            }}
          >
            {isLogo ? (
              (logo ?? <RemocnLogo fontSize={brandSize} color="#FFFFFF" />)
            ) : (
              <div
                style={{
                  fontFamily: manrope.fontFamily,
                  fontWeight: 500,
                  fontSize: brandSize,
                  lineHeight: 1,
                  letterSpacing: "-0.035em",
                  color: "#FFFFFF",
                }}
              >
                {center}
              </div>
            )}
          </div>

          {caption ? (
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top:
                  cy + (three ? finalSep / Math.sqrt(3) / 2 : 0) + R + 34 * u,
                textAlign: "center",
                fontFamily: manrope.fontFamily,
                fontWeight: 400,
                fontSize: 24 * u,
                letterSpacing: "-0.01em",
                color: p.muted,
                opacity: capIn,
                transform: `translateY(${(1 - capIn) * 10 * u}px)`,
                textWrap: "balance",
              }}
            >
              {caption}
            </div>
          ) : null}
        </AbsoluteFill>
      </ScaleLayer>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 62%, ${bg} 100%)`,
          opacity: 0.55,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  center: {
    type: "text-content",
    default: "remocn",
    description: "Center",
  },
  caption: {
    type: "text-content",
    default: "Motion design, written as code.",
    description: "Caption",
  },
  slide: {
    type: "number",
    default: 40,
    min: 10,
    max: 90,
    step: 1,
    description: "Slide (frames)",
    hiddenFromList: false,
  },
  ringWidth: {
    type: "number",
    default: 2,
    min: 1,
    max: 8,
    step: 0.5,
    description: "Ring width",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Instrument Serif",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","center","caption","slide","ringWidth","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  center: "remocn",
  caption: "Motion design, written as code.",
  slide: 40,
  ringWidth: 2,
  accent: "#3B5BFD",
  fontFamily: "Instrument Serif",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type VennMergeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof VennMergeBase>;

const VennMergeInner = forwardRef<
  HTMLDivElement,
  VennMergeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<VennMerge>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <VennMergeBase
          {...(componentProps as unknown as ComponentProps<typeof VennMergeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const VennMerge = Interactive.withSchema({
  Component: VennMergeInner,
  componentName: "<VennMerge>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
